 public partial class Library {
  internal string RestoredLibraryDirectory="";
  static bool Below(string path,string root){return Path.GetFullPath(path).StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
  static void ZipText(ZipArchive zip,string name,string text){using(var writer=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))writer.Write(text);}
  static string HashBytes(byte[] data){using(var sha=SHA256.Create())return String.Concat(sha.ComputeHash(data).Select(b=>b.ToString("x2")));}
  static string HashStream(Stream input){using(var sha=SHA256.Create())return String.Concat(sha.ComputeHash(input).Select(b=>b.ToString("x2")));}
  public object ExportKnowledge(string destination,bool includeOriginals,CancellationToken token,string referenceRoot=""){
   EnsureNormalContent();referenceRoot=String.IsNullOrWhiteSpace(referenceRoot)?"":Path.GetFullPath(referenceRoot);if(referenceRoot!=""&&!Directory.Exists(referenceRoot))throw new InvalidDataException("Choose an existing reference root.");destination=Path.GetFullPath(destination);if(Below(destination,DataDir))throw new InvalidDataException("Save the export outside the active data directory.");PortableLibrary data;Dictionary<string,string> stamps;lock(gate){data=new PortableLibrary{created=DateTime.UtcNow.ToString("o"),producer=AppVersion.Current,items=Db.items.Select(e=>Json.Deserialize<Entry>(Json.Serialize(e))).ToList(),workspace=Json.Deserialize<WorkspaceState>(Json.Serialize(Db.workspace)),collections=Db.collections.ToList()};stamps=data.items.ToDictionary(e=>e.id,e=>ContentStamp(e.id));}
   if(data.items.Count>10000)throw new InvalidDataException("Portable libraries support at most 10,000 sources per archive.");
   string temp=destination+".tmp-"+Guid.NewGuid().ToString("N");int copied=0;long total=0;
   try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){
    foreach(var item in data.items){token.ThrowIfCancellationRequested();item.aiChat=new List<ChatTurn>();item.aiStudies=new List<StudyReport>();item.agentOperationId="";string original=item.path;item.hasCover=false;item.coverVersion="";
     if((includeOriginals||item.ownedDocument)&&File.Exists(original)){var info=new FileInfo(original);if(info.Length>2L*1024*1024*1024||total+info.Length>8L*1024*1024*1024)throw new InvalidDataException("Export exceeds the 8 GB total or 2 GB per-file limit.");string file="sources/"+item.id+"."+item.ext.ToLowerInvariant();using(var input=new FileStream(original,FileMode.Open,FileAccess.Read,FileShare.Read))using(var entry=zip.CreateEntry(file,CompressionLevel.Fastest).Open()){var bytes=new byte[65536];int read;while((read=input.Read(bytes,0,bytes.Length))>0){token.ThrowIfCancellationRequested();entry.Write(bytes,0,read);}input.Position=0;data.files.Add(new PortableFile{itemId=item.id,file=file,size=input.Length,sha256=HashStream(input)});}total+=info.Length;copied++;}
     // v2 never records machine-specific absolute paths. Nested external layout is opt-in.
     var included=data.files.FirstOrDefault(f=>f.itemId==item.id);
     item.path=included!=null?included.file:(referenceRoot!=""&&Below(original,referenceRoot)?Path.GetFullPath(original).Substring(referenceRoot.TrimEnd(Path.DirectorySeparatorChar).Length+1):Path.GetFileName(original)).Replace('\\','/');
     if(!PortableRelative(item.path))throw new InvalidDataException("Invalid portable source reference.");
     var note=new StringBuilder("# "+item.name+"\n\n");note.Append("kok-id: "+item.id+"\n\n");if(item.sourceInfo!=null&&!String.IsNullOrEmpty(item.sourceInfo.url))note.Append("Source: "+item.sourceInfo.url+"\n\n");if(item.ownedDocument&&new[]{"MD","TXT","DOCX"}.Contains(item.ext)&&File.Exists(original)){note.Append(DocumentSource(item.id).text);note.Append("\n\n");}note.Append(item.notes??"");foreach(var clip in data.workspace.clips.Where(c=>c.source!=null&&c.source.itemId==item.id))note.Append("\n\n## "+clip.title+"\n\n"+clip.text+"\n\nSource ID: "+item.id+"; page: "+clip.source.page+"; chapter: "+clip.source.chapter+"; time: "+clip.source.time.ToString(System.Globalization.CultureInfo.InvariantCulture));ZipText(zip,"notes/"+item.id+".md",note.ToString());
    }
    ZipText(zip,"clips.json",Json.Serialize(data.workspace.clips));ZipText(zip,"spaces.json",Json.Serialize(data.workspace.spaces));ZipText(zip,"manifest.json",Json.Serialize(data));
   }lock(gate){if(stamps.Any(p=>ContentStamp(p.Key)!=p.Value)||Db.items.Count!=data.items.Count||Json.Serialize(Db.workspace)!=Json.Serialize(data.workspace))throw new InvalidDataException("Library changed during export; retry after pending edits finish.");}token.ThrowIfCancellationRequested();if(File.Exists(destination))File.Replace(temp,destination,null);else File.Move(temp,destination);return new{saved=true,items=data.items.Count,files=copied,bytes=total};}finally{if(File.Exists(temp))File.Delete(temp);}
  }
  static bool PortableRelative(string value){return !String.IsNullOrWhiteSpace(value)&&value.Length<=4000&&!Path.IsPathRooted(value)&&!value.Contains(":")&&!value.Contains("\\")&&value.Split('/').All(p=>p!=""&&p!="."&&p!="..");}
  static PortableLibrary ReadPortable(ZipArchive zip){
   if(zip.Entries.Count>100000||zip.Entries.Select(e=>e.FullName).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=zip.Entries.Count)throw new InvalidDataException("Archive contains too many or duplicate entries.");var manifest=zip.GetEntry("manifest.json");if(manifest==null||manifest.Length>64*1024*1024)throw new InvalidDataException("Not a supported kok portable library.");PortableLibrary data;using(var reader=new StreamReader(manifest.Open(),Encoding.UTF8))data=Json.Deserialize<PortableLibrary>(reader.ReadToEnd());
   if(data==null||data.format!="kok.portable"||(data.version!=1&&data.version!=2)||data.items==null||data.items.Count>10000||data.items.Any(e=>e==null||data.version==2&&!PortableRelative(e.path)||!AgentJournal.ValidId(e.id)||String.IsNullOrWhiteSpace(e.name)||e.name.Length>300||e.ext==null||!System.Text.RegularExpressions.Regex.IsMatch(e.ext,"^[A-Za-z0-9]{1,12}$")||!new[]{"video","music","photo","document","book"}.Contains(e.kind))||data.items.Select(e=>e.id).Distinct().Count()!=data.items.Count||data.files==null||data.files.Count>data.items.Count||data.files.Any(f=>f==null||!data.items.Any(e=>e.id==f.itemId)||f.file!="sources/"+f.itemId+"."+data.items.First(e=>e.id==f.itemId).ext.ToLowerInvariant()||f.sha256==null||!System.Text.RegularExpressions.Regex.IsMatch(f.sha256,"^[a-f0-9]{64}$")||f.size<0||f.size>2L*1024*1024*1024)||data.files.Select(f=>f.itemId).Distinct().Count()!=data.files.Count||data.files.Sum(f=>f.size)>8L*1024*1024*1024||data.workspace==null||data.workspace.clips==null||data.workspace.spaces==null||data.workspace.queries==null||data.workspace.recipes==null||data.collections==null)throw new InvalidDataException("Invalid portable library manifest.");return data;
  }
  public object PreviewKnowledgeRestore(string archive){EnsureNormalContent();using(var zip=ZipFile.OpenRead(archive)){var data=ReadPortable(zip);return new{items=data.items.Count,files=data.files.Count,clips=data.workspace.clips.Count,spaces=data.workspace.spaces.Count,externalReferences=data.items.Count-data.files.Count,created=data.created,producer=data.producer};}}
  public object RestoreKnowledge(string archive,string target,string oldRoot,string newRoot,CancellationToken token){
   EnsureNormalContent();target=Path.GetFullPath(target);if(Directory.Exists(target)||File.Exists(target)||Below(target,DataDir)||Below(DataDir,target))throw new InvalidDataException("Restore into a new directory outside the active data directory.");string stage=target+".restore-"+Guid.NewGuid().ToString("N"),parent=Path.GetDirectoryName(target);Directory.CreateDirectory(parent);if(!Below(stage,parent)||!Below(target,parent))throw new InvalidDataException("Invalid restore destination.");bool moved=false;Directory.CreateDirectory(stage);
   try{using(var zip=ZipFile.OpenRead(archive)){var data=ReadPortable(zip);var identities=new HashSet<string>(data.items.Select(e=>e.id));foreach(var clip in data.workspace.clips){if(clip==null||!AgentJournal.ValidId(clip.id)||clip.source==null||!identities.Contains(clip.source.itemId))throw new InvalidDataException("Clip references an unknown source.");if(!identities.Add(clip.id))throw new InvalidDataException("Duplicate restored identity.");}foreach(var space in data.workspace.spaces)if(space==null||space.members==null||space.members.Any(id=>!identities.Contains(id)))throw new InvalidDataException("Space references an unknown source.");
    var restored=new Library(stage);foreach(var space in data.workspace.spaces)restored.ValidateResource("space",space.id,Json.Serialize(space));foreach(var clip in data.workspace.clips)restored.ValidateResource("clip",clip.id,Json.Serialize(clip));foreach(var query in data.workspace.queries)restored.ValidateResource("query",query.id,Json.Serialize(query));foreach(var recipe in data.workspace.recipes)restored.ValidateResource("recipe",recipe.id,Json.Serialize(recipe));int missing=0;
    foreach(var item in data.items){token.ThrowIfCancellationRequested();var stored=data.files.FirstOrDefault(f=>f.itemId==item.id);if(stored!=null){var entry=zip.GetEntry(stored.file);if(entry==null||entry.Length!=stored.size)throw new InvalidDataException("Archive attachment is missing or has an invalid size.");string relative=Path.Combine(item.ownedDocument?"documents":"sources",item.id+"."+item.ext.ToLowerInvariant()),output=Path.Combine(stage,relative);if(!Below(output,stage))throw new InvalidDataException("Attachment path escapes the restored library.");Directory.CreateDirectory(Path.GetDirectoryName(output));using(var input=entry.Open())using(var file=new FileStream(output,FileMode.CreateNew)){var bytes=new byte[65536];int read;long count=0;while((read=input.Read(bytes,0,bytes.Length))>0){token.ThrowIfCancellationRequested();count+=read;if(count>stored.size)throw new InvalidDataException("Attachment exceeds its declared size.");file.Write(bytes,0,read);}}using(var file=File.OpenRead(output))if(HashStream(file)!=stored.sha256)throw new InvalidDataException("Attachment checksum failed.");item.path=Path.Combine(target,relative);}
     else{string mapped=null;
      if(data.version==2&&!String.IsNullOrWhiteSpace(newRoot)){mapped=Path.GetFullPath(Path.Combine(newRoot,item.path.Replace('/',Path.DirectorySeparatorChar)));if(!Below(mapped,newRoot)||!File.Exists(mapped)||Classify(mapped)!=item.kind)mapped=null;}
      if(data.version==1&&!String.IsNullOrWhiteSpace(oldRoot)&&!String.IsNullOrWhiteSpace(newRoot)&&!String.IsNullOrWhiteSpace(item.path)&&Below(item.path,oldRoot)){string suffix=Path.GetFullPath(item.path).Substring(Path.GetFullPath(oldRoot).TrimEnd(Path.DirectorySeparatorChar).Length+1);mapped=Path.GetFullPath(Path.Combine(newRoot,suffix));if(!Below(mapped,newRoot)||!File.Exists(mapped)||Classify(mapped)!=item.kind)mapped=null;}item.path=mapped??Path.Combine(target,"missing",item.id+"."+item.ext.ToLowerInvariant());item.ownedDocument=false;if(mapped==null)missing++;}item.aiChat=new List<ChatTurn>();item.aiStudies=new List<StudyReport>();item.hasCover=false;item.agentOperationId="";restored.Db.items.Add(item);
    }restored.Db.collections=data.collections;restored.Db.workspace=data.workspace;restored.Db.settings=new Dictionary<string,object>{{"appMode","pure"}};restored.Save(false,null,new string[0],true);token.ThrowIfCancellationRequested();Directory.Move(stage,target);moved=true;lock(gate)RestoredLibraryDirectory=target;return new{restored=true,items=data.items.Count,missing,directory=target};}
   }finally{if(!moved&&Directory.Exists(stage)&&Below(stage,parent)&&Path.GetFileName(stage).StartsWith(Path.GetFileName(target)+".restore-",StringComparison.Ordinal))Directory.Delete(stage,true);}
  }
  internal sealed class PreparedCapture {internal CaptureRequest request;internal byte[] image;internal string fingerprint;}
  internal static PreparedCapture PrepareCapture(CaptureRequest request,CancellationToken token){
   token.ThrowIfCancellationRequested();
   if(request==null||request.title==null||request.title.Length>200||request.text==null||request.text.Length>200000||request.url==null||request.url.Length>4000||request.imageBase64==null||request.imageBase64.Length>16*1024*1024)throw new InvalidDataException("Capture is empty or exceeds its size limit.");
   request=new CaptureRequest{title=request.title,text=request.text,url=request.url,imageBase64=request.imageBase64};
   if(request.url!=""){Uri uri;if(!Uri.TryCreate(request.url,UriKind.Absolute,out uri)||!new[]{"http","https"}.Contains(uri.Scheme)||uri.UserInfo!="")throw new InvalidDataException("Capture source must be an HTTP or HTTPS URL.");}
   if(String.IsNullOrWhiteSpace(request.text)&&request.url==""&&request.imageBase64=="")throw new InvalidDataException("Capture has no content.");
   var ready=new PreparedCapture{request=request,fingerprint=StudyHash(new{request.text,request.url,request.imageBase64})};
   if(request.imageBase64!=""){
    byte[] bytes;try{bytes=Convert.FromBase64String(request.imageBase64);}catch{throw new InvalidDataException("Invalid captured image.");}
    if(bytes.Length>12*1024*1024)throw new InvalidDataException("Captured image is too large.");
    using(var stream=new MemoryStream(bytes))using(var image=System.Drawing.Image.FromStream(stream)){
     if((long)image.Width*image.Height>40000000)throw new InvalidDataException("Captured image dimensions are too large.");
     token.ThrowIfCancellationRequested();using(var bitmap=new System.Drawing.Bitmap(image))using(var png=new MemoryStream()){bitmap.Save(png,System.Drawing.Imaging.ImageFormat.Png);if(png.Length>24*1024*1024)throw new InvalidDataException("Re-encoded capture is too large.");ready.image=png.ToArray();}
    }
   }
   token.ThrowIfCancellationRequested();return ready;
  }
  public Entry CaptureSource(CaptureRequest request){return CapturePrepared(PrepareCapture(request,CancellationToken.None));}
  internal Entry CapturePrepared(PreparedCapture ready){
   EnsureNormalContent();var request=ready.request;string fingerprint=ready.fingerprint;
   lock(gate){
    var existing=Db.items.FirstOrDefault(e=>e.sourceInfo!=null&&e.sourceInfo.fingerprint==fingerprint||e.agentOperationId==fingerprint.Substring(0,32));if(existing!=null)return existing;
    string title=String.IsNullOrWhiteSpace(request.title)?"Capture "+DateTime.Now.ToString("yyyy-MM-dd HHmmss"):request.title.Trim();title=String.Concat(title.Select(ch=>Path.GetInvalidFileNameChars().Contains(ch)?'_':ch)).Trim().TrimEnd('.');if(title.Length>100)title=title.Substring(0,100);if(title==""||System.Text.RegularExpressions.Regex.IsMatch(title,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)",System.Text.RegularExpressions.RegexOptions.IgnoreCase))title="Capture "+title;
    Entry result;
    if(ready.image!=null){string folder=Path.Combine(DataDir,"captures");Directory.CreateDirectory(folder);string file=Path.Combine(folder,Guid.NewGuid().ToString("N")+".png");File.WriteAllBytes(file,ready.image);try{Import(new[]{file},null);result=Db.items.First(e=>e.path==file);}catch{if(!Db.items.Any(e=>e.path==file)&&File.Exists(file))File.Delete(file);throw;}result.name=title;result.collection="Inbox";result.notes=request.text;}
    else result=CreateDocument(title,"md","Inbox",(request.url==""?"":"Source: ["+request.url.Replace("]","%5D")+"]("+request.url.Replace(")","%29")+")\n\n")+request.text,fingerprint.Substring(0,32),"capture");
    result.sourceInfo=new CaptureOrigin{url=request.url,captured=DateTime.UtcNow.ToString("o"),kind=ready.image==null?"text":"image",fingerprint=fingerprint};if(!Db.collections.Contains("Inbox"))Db.collections.Add("Inbox");Save();return result;
   }
  }
  public Operation ProposeRelink(string id,string path,string stamp){EnsureNormalContent();lock(gate){var item=Find(id);if(item==null||ContentStamp(id)!=stamp||!File.Exists(path)||Classify(path)!=item.kind||!String.Equals(Path.GetExtension(path).TrimStart('.'),item.ext,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Relink target is unavailable, has a different format, or the source changed.");var copy=Json.Deserialize<Entry>(Json.Serialize(item));copy.path=Path.GetFullPath(path);if(!Below(copy.path,DocumentDirectory))copy.ownedDocument=false;return ProposeResource("item",id,Json.Serialize(copy));}}
  public object FindExactDuplicates(CancellationToken token){EnsureNormalContent();var groups=new List<object>();var entries=ContentEntries().Where(e=>File.Exists(e.path)).ToArray();foreach(var group in entries.GroupBy(e=>new FileInfo(e.path).Length).Where(g=>g.Count()>1)){var hashes=new Dictionary<string,List<string>>();foreach(var e in group){token.ThrowIfCancellationRequested();string hash;try{using(var input=File.OpenRead(e.path))hash=HashStream(input);}catch(IOException){continue;}List<string> ids;if(!hashes.TryGetValue(hash,out ids))hashes[hash]=ids=new List<string>();ids.Add(e.id);}foreach(var pair in hashes.Where(p=>p.Value.Count>1))groups.Add(new{ids=pair.Value,sha256=pair.Key});}return groups;}
 }
