  internal static IEnumerable<ActionSpec> Actions(){return new[]{
   ModuleDefinitions.Action("captureSource",Need.NormalLibrary,true,async(c,a)=>{var ready=await Task.Run(()=>Library.PrepareCapture(AgentTaskState.Get<CaptureRequest>(a,"capture"),c.Jobs.CurrentToken));c.Policy.Ensure(Need.NormalLibrary,"workspace");var item=c.Library.CapturePrepared(ready);c.Notify("libraryChanged",null);return (object)item;},CapabilitySchema.Obj(CapabilitySchema.Fields("capture",CapabilitySchema.Obj(CapabilitySchema.Fields("title",CapabilitySchema.Str(200),"text",CapabilitySchema.Str(200000),"url",CapabilitySchema.Str(4000),"imageBase64",CapabilitySchema.Str(16*1024*1024)))),new[]{"capture"})),
   ModuleDefinitions.Action("exportKnowledge",Need.NormalLibrary,true,async(c,a)=>{using(var dialog=new SaveFileDialog{Filter="kok portable library (*.koklib)|*.koklib",FileName="kok-library-"+DateTime.Now.ToString("yyyyMMdd")+".koklib"}){if(dialog.ShowDialog(c.Owner)!=DialogResult.OK)return new{cancelled=true};using(c.BeginWrite())return await Task.Run(()=>c.Library.ExportKnowledge(dialog.FileName,a.ContainsKey("includeOriginals")&&Convert.ToBoolean(a["includeOriginals"]),c.Jobs.CurrentToken,ModuleContext.Text(a,"referenceRoot")));}},CapabilitySchema.Obj(CapabilitySchema.Fields("includeOriginals",new Dictionary<string,object>{{"type","boolean"}},"referenceRoot",CapabilitySchema.Str(4000)))),
   ModuleDefinitions.Action("restoreKnowledge",Need.NormalLibrary,true,async(c,a)=>{using(var file=new OpenFileDialog{Filter="kok portable library (*.koklib)|*.koklib"}){if(file.ShowDialog(c.Owner)!=DialogResult.OK)return new{cancelled=true};var preview=c.Library.PreviewKnowledgeRestore(file.FileName);if(MessageBox.Show(c.Owner,RestorePrompt(c,preview),"kok",MessageBoxButtons.OKCancel)!=DialogResult.OK)return new{cancelled=true};using(var folder=new FolderBrowserDialog{Description=English(c)?"Choose where to create the restored library":"选择新资料库所在的文件夹"}){if(folder.ShowDialog(c.Owner)!=DialogResult.OK)return new{cancelled=true};string target=Path.Combine(folder.SelectedPath,"kok-restored-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));using(c.BeginWrite())return await Task.Run(()=>c.Library.RestoreKnowledge(file.FileName,target,ModuleContext.Text(a,"oldRoot"),ModuleContext.Text(a,"newRoot"),c.Jobs.CurrentToken));}}},CapabilitySchema.Obj(CapabilitySchema.Fields("oldRoot",CapabilitySchema.Str(1000),"newRoot",CapabilitySchema.Str(1000)))),
   ModuleDefinitions.Action("relinkSource",Need.NormalLibrary,true,(c,a)=>{string id=ModuleContext.Text(a,"id"),stamp=c.Library.ContentStamp(id);using(var file=new OpenFileDialog()){if(file.ShowDialog(c.Owner)!=DialogResult.OK)return Task.FromResult((object)new{cancelled=true});return Task.FromResult((object)c.Library.ProposeRelink(id,file.FileName,stamp));}},CapabilitySchema.Obj(CapabilitySchema.Fields("id",CapabilitySchema.Str(32)),new[]{"id"})),
   ModuleDefinitions.Action("exactDuplicates",Need.NormalLibrary,false,async(c,a)=>(object)await Task.Run(()=>c.Library.FindExactDuplicates(c.Jobs.CurrentToken)),CapabilitySchema.Obj())
   ,ModuleDefinitions.Action("openRestoredKnowledge",Need.NormalLibrary,true,(c,a)=>{string path=c.Library.RestoredLibraryDirectory;if(path==""||!Directory.Exists(path))throw new InvalidOperationException(English(c)?"Restore a library first.":"请先恢复一份资料库。");Process.Start(new ProcessStartInfo{FileName=Path.Combine(c.AppDirectory,"kok.exe"),Arguments="--data-dir \""+path+"\"",UseShellExecute=false});return Task.FromResult((object)new{opened=true});},CapabilitySchema.Obj())
  };}
 }
